// hw-power — generated from src/hw-power-*.js by tools/merge.js. Edit the src files, then run: node tools/merge.js
// Power Electronics Engineer. Format: [topic, question, answer, 'B'|'D', 'E'|'M'|'S'|'X', source, { t: top, f: [follow-up q, a] }]
QB["hw-power"] = (QB["hw-power"] || []).concat([
["Role overview", "What does a power electronics engineer do?", "**Why they ask:** the opening question.\n\n**Answer:**\n\"I design circuits that convert and control electrical power efficiently — DC-DC converters, AC-DC power supplies, motor drives or battery chargers. That covers choosing the topology, selecting switches and magnetics, designing the control loop, thermal design, and meeting safety and EMC standards. Then a lot of lab work: measuring efficiency, ripple, transient response and loop stability, and testing faults like short circuits.\"\n\nTip: Show you cover the full design, not just the schematic.", "B", "M", null, {"t":1,"f":["What power levels have you worked with?","From small point-of-load converters of a few watts up to a 1 kW AC-DC supply."]}],
["Topologies", "How do you choose between buck, boost, flyback and other topologies?", "**Why they ask:** core design judgement.\n\n**Answer:**\n\"It depends on the input and output voltages, power level and whether isolation is needed. Buck steps down, boost steps up, buck-boost handles both. If I need isolation at lower power, a flyback is simple and cheap; at higher power, a forward, half-bridge or full-bridge topology is more efficient, and LLC resonant converters give high efficiency at a few hundred watts and up. I also weigh cost, size and EMC.\"\n\nTip: Isolation and power level are the two main deciders.", "D", "M", null, {"t":1,"f":["Why is a flyback common for low-power isolated supplies?","It uses few parts — the transformer also stores energy — so it's cheap and simple up to around 100 watts."]}],
["Control loop", "How do you make sure a converter's control loop is stable?", "**Why they ask:** unstable loops oscillate or fail.\n\n**Answer:**\n\"I model the power stage and design compensation to reach a target crossover frequency — often a fraction of the switching frequency — with at least 45 to 60 degrees of phase margin and about 10 dB of gain margin. Then I measure the real loop with a frequency response analyzer by injecting a signal into the loop, and confirm with load step tests. I check across input voltage, load and temperature, because margins change.\"\n\nTip: Quote phase and gain margin targets.", "D", "S", null, {"t":1,"f":["What does a load step test show?","How fast and how cleanly the output recovers from a sudden load change — ringing means low phase margin."]}],
["Magnetics", "How do you design or select an inductor?", "**Why they ask:** magnetics drive size and losses.\n\n**Answer:**\n\"I calculate the inductance from the allowed ripple current — often 20 to 40 percent of the load current. Then I make sure the saturation current is above the peak current with margin, check the RMS current against its heating rating, and estimate core and winding losses at the switching frequency. For custom transformers I work with a magnetics vendor on turns ratio, insulation and leakage inductance.\"\n\nTip: Saturation margin is the critical check.", "D", "M", null, {"f":["What happens when an inductor saturates?","Its inductance drops sharply, current spikes, and the switch can fail."]}],
["Switches", "How do you choose between silicon MOSFETs, SiC and GaN?", "**Why they ask:** wide-bandgap devices are a big trend.\n\n**Answer:**\n\"Silicon MOSFETs are cheap and fine for most low and medium-voltage designs. Gallium nitride switches very fast with low losses, which allows higher frequency and smaller magnetics — great for compact chargers up to a few hundred volts. Silicon carbide handles high voltage and temperature well, so it's used in EV inverters and industrial drives. The trade-offs are cost, gate drive needs, and layout sensitivity, since fast edges cause more ringing and EMI.\"\n\nTip: Match each device to its sweet spot.", "D", "S", null, {"f":["Why is layout more critical with GaN?","Its very fast switching makes small parasitic inductances cause big voltage spikes and ringing."]}],
["Efficiency", "Where do losses come from in a converter, and how do you reduce them?", "**Why they ask:** efficiency drives heat and size.\n\n**Answer:**\n\"Conduction losses in switches and windings, switching losses when transistors turn on and off, gate drive losses, and core losses in magnetics. To cut them I pick switches with the right balance of on-resistance and charge for the frequency, use synchronous rectification instead of diodes, optimize the switching frequency, and choose low-loss magnetics. Soft-switching topologies can reduce switching loss a lot. I measure efficiency across the load range, because light-load efficiency often matters too.\"\n\nTip: Split losses into conduction and switching.", "D", "M", null, {"f":["Why use synchronous rectification?","A MOSFET has much lower voltage drop than a diode at higher currents, so it wastes less power."]}],
["Thermal", "How do you handle thermal design for a power supply?", "**Why they ask:** heat limits reliability.\n\n**Answer:**\n\"From the loss estimate for each component, I calculate junction temperatures using thermal resistances, then choose cooling — copper area, heat sinks or airflow — to keep parts below their limits with margin. I keep electrolytic capacitors cool, since their life halves roughly every 10 degrees hotter. Then I verify with thermocouples and a thermal camera at worst-case load and ambient.\"\n\nTip: Capacitor life is a strong practical point.", "B", "M", null, {"f":["What is derating?","Running a part below its maximum rating — like 80 percent of voltage — to improve reliability."]}],
["Safety", "What safety considerations apply to an AC-DC power supply?", "**Why they ask:** mains-powered products must be safe.\n\n**Answer:**\n\"Isolation between the mains side and the user side — the right insulation level, creepage and clearance distances, and safety-rated components like Y-capacitors and approved transformers. Protection against overcurrent, overvoltage and overtemperature, and fusing. Limiting leakage current. Designing to the relevant standard, like IEC 62368-1, and planning for certification testing.\"\n\nTip: Name creepage, clearance and the standard.", "D", "S", null, {"f":["What's the difference between creepage and clearance?","Clearance is the shortest distance through air; creepage is the shortest distance along a surface between conductors."]}],
["EMI", "How do you keep a switching supply's EMI under control?", "**Why they ask:** switchers are noisy.\n\n**Answer:**\n\"Mostly through layout — the smallest possible hot loop for the switching current, a small switch node, and a solid ground. I add input filtering — differential and common-mode — sized for the conducted emissions limits, slow switching edges a little with gate resistors or snubbers if needed, and consider spread-spectrum frequency modulation. I do pre-compliance scans early.\"\n\nTip: Layout first, filters second.", "D", "M", null, {"f":["What is a snubber?","A small RC or RCD network across a switch that damps ringing and voltage spikes."]}],
["Protection", "How do you protect a converter against faults?", "**Why they ask:** robustness.\n\n**Answer:**\n\"Cycle-by-cycle current limiting, short-circuit protection with hiccup or latch-off, overvoltage protection on the output, undervoltage lockout on the input, thermal shutdown, and soft-start to limit inrush. Then I test each fault deliberately in the lab — short the output, overload it, overheat it — to prove the supply survives.\"\n\nTip: Say you test faults on purpose.", "B", "M", null, {"f":["What is hiccup mode?","On a short circuit the converter shuts off and retries periodically, which keeps heat low until the fault is removed."]}],
["Behavioral", "Tell me about a power design problem you solved.", "**Why they ask:** real experience.\n\n**Answer:**\n\"A 48 V to 12 V converter failed in testing when the output was shorted at high temperature. Measurements showed the current limit triggered too late because the sense resistor heated up and its value changed. We changed to a lower-drift resistor and adjusted the limit with margin across temperature. It then passed hundreds of short-circuit cycles at temperature.\"\n\nTip: Show root cause through measurement.", "B", "M", null, {"f":["How did you find the cause?","Logged the current limit trip point across temperature and saw it drift with the sense resistor's heating."]}],
["Closing", "Why do you want this power electronics role?", "**Why they ask:** motivation and fit.\n\n**Answer:**\n\"Power electronics is central to electrification — EVs, renewables, data centers — and efficiency directly saves energy. Your work on high-density converters matches my experience with GaN and control loop design, and I'd like to grow into owning the power architecture of a product.\"\n\nTip: Connect to the larger trend and their product.", "B", "M", null, {"f":["Which area of power electronics interests you most?","High-density, high-efficiency conversion using wide-bandgap devices."]}]
]);

